import{_ as a,b as n,f as l,I as e}from"./chunks/framework.DYvp_Vyw.js";const y=JSON.parse('{"title":"Matlab学习笔记005 - 线性代数中的数学计算问题","description":"","frontmatter":{"title":"Matlab学习笔记005 - 线性代数中的数学计算问题","date":"2025-05-06T12:33:10.000Z","tags":["数学建模","Matlab"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Matlab-Own-Study-005.md","filePath":"posts/Matlab-Own-Study-005.md"}'),p={name:"posts/Matlab-Own-Study-005.md"};function o(t,s,r,c,i,d){return l(),n("div",null,s[0]||(s[0]=[e(`<p>自己学习后整理的笔记（实时更新）</p><hr><h2 id="一、特殊矩阵的实现" tabindex="-1">一、特殊矩阵的实现 <a class="header-anchor" href="#一、特殊矩阵的实现" aria-label="Permalink to &quot;一、特殊矩阵的实现&quot;">​</a></h2><blockquote><p>常见的特殊矩阵有零矩阵、幺矩阵、单位矩阵、三角形矩阵等，这类特殊矩阵在线性代数中具有通用性；还有一类特殊矩阵在专门学科中有用，如有名的希尔伯特(Hilbert)矩阵、范德蒙(Vandermonde) 矩阵等。</p></blockquote><h3 id="_1-零矩阵" tabindex="-1">1. 零矩阵 <a class="header-anchor" href="#_1-零矩阵" aria-label="Permalink to &quot;1. 零矩阵&quot;">​</a></h3><p>所有元素值为零的矩阵称为零矩阵。零矩阵可以用zeros函数实现。zeros是MATLAB内部函数，使用格式如下： zeros(m)：产生m m阶零矩阵； zeros(m,n)：产生m n阶零矩阵，当m=n时等同于zeros(m)； zeros(size(A))：产生与矩阵A同样大小的零矩阵。 所有元素值为零的矩阵。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 示例代码</span></span>
<span class="line"><span style="color:#839496;">Z1 = zeros(</span><span style="color:#D33682;">3</span><span style="color:#839496;">);       </span><span style="color:#586E75;font-style:italic;">% 3×3零矩阵</span></span>
<span class="line"><span style="color:#839496;">Z2 = zeros(</span><span style="color:#D33682;">2</span><span style="color:#839496;">,</span><span style="color:#D33682;">4</span><span style="color:#839496;">);      </span><span style="color:#586E75;font-style:italic;">% 2×4零矩阵</span></span>
<span class="line"><span style="color:#839496;">A = rand(</span><span style="color:#D33682;">3</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#839496;">Z3 = zeros(size(A));  </span><span style="color:#586E75;font-style:italic;">% 与A同维的零矩阵</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_2-幺矩阵" tabindex="-1">2. 幺矩阵 <a class="header-anchor" href="#_2-幺矩阵" aria-label="Permalink to &quot;2. 幺矩阵&quot;">​</a></h3><p>所有元素值为1的矩阵称为幺矩阵。幺矩阵可以用ones函数实现。它的调用格式与zeros函数一样。 所有元素值为1的矩阵。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 示例代码</span></span>
<span class="line"><span style="color:#839496;">O1 = ones(</span><span style="color:#D33682;">3</span><span style="color:#839496;">);        </span><span style="color:#586E75;font-style:italic;">% 3×3幺矩阵</span></span>
<span class="line"><span style="color:#839496;">O2 = ones(</span><span style="color:#D33682;">1</span><span style="color:#839496;">,</span><span style="color:#D33682;">5</span><span style="color:#839496;">);      </span><span style="color:#586E75;font-style:italic;">% 1×5幺矩阵</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_3-单位矩阵" tabindex="-1">3. 单位矩阵 <a class="header-anchor" href="#_3-单位矩阵" aria-label="Permalink to &quot;3. 单位矩阵&quot;">​</a></h3><p>主对角线的元素值为1、其余元素值为0的矩阵称为单位矩阵。它可以用MATLAB内部函数eye建立，使用格式与zeros相同。 主对角线为1，其余为0的矩阵。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 示例代码</span></span>
<span class="line"><span style="color:#839496;">I1 = eye(</span><span style="color:#D33682;">4</span><span style="color:#839496;">);         </span><span style="color:#586E75;font-style:italic;">% 4×4单位矩阵</span></span>
<span class="line"><span style="color:#839496;">I2 = eye(</span><span style="color:#D33682;">3</span><span style="color:#839496;">,</span><span style="color:#D33682;">5</span><span style="color:#839496;">);       </span><span style="color:#586E75;font-style:italic;">% 3×5矩形单位矩阵</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_4-数量矩阵" tabindex="-1">4. 数量矩阵 <a class="header-anchor" href="#_4-数量矩阵" aria-label="Permalink to &quot;4. 数量矩阵&quot;">​</a></h3><p>主对角线的元素值为一常数d、其余元素值为0的矩阵称为数量矩阵。显然，当d=1时，即为单位矩阵，故数量矩阵可以用<code>eye(m)*d</code>或<code>eye(m,n)*d</code>建立。 主对角线为常数d的矩阵。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 示例代码</span></span>
<span class="line"><span style="color:#839496;">d = </span><span style="color:#D33682;">2.5</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#839496;">D1 = eye(</span><span style="color:#D33682;">3</span><span style="color:#839496;">)*d;       </span><span style="color:#586E75;font-style:italic;">% 3×3数量矩阵</span></span>
<span class="line"><span style="color:#839496;">D2 = eye(</span><span style="color:#D33682;">2</span><span style="color:#839496;">,</span><span style="color:#D33682;">4</span><span style="color:#839496;">)*d;     </span><span style="color:#586E75;font-style:italic;">% 2×4矩形数量矩阵</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_5-7-对角阵" tabindex="-1">5-7. 对角阵 <a class="header-anchor" href="#_5-7-对角阵" aria-label="Permalink to &quot;5-7. 对角阵&quot;">​</a></h3><p>对角线的元素值为常数、其余元素值为0的矩阵称为对角阵。我们可以通过MATLAB内部函数diag，利用一个向量构成对角阵；或从矩阵中提取某对角线构成一个向量。使用 格式为diag(V)和diag(V,k)两种。</p><p>设V为具有m个元素的向量，diag(V)将产生一个mm阶对角阵，其主对角线的元素值即为向量的元素值；diag(V,k)将产生一个nn(n=m+|k|，k为一整数)阶对角阵，其第k条对角线的元素值即为向量的元素值。注意：当k＞0，则该对角线位于主对角线的上方第k条；当k＜0，该对角线位于主对角线的下方第|k|条；当k=0，则等同于diag(V)。用diag建立的对角阵必是方阵。</p><p>我们也可以用diag从矩阵中提取某对角线构成一个向量。设A为m  n阶矩阵，diag(A)将从矩阵A中提取其主对角线产生一个具有min(m,n)个元素的向量。diag(A,k)的功能是： 当k＞0，则将从矩阵A中提取位于主对角线的上方第k条对角线构成一个具有n-k个元素的向量；当k＜0，则将从矩阵A中提取位于主对角线的下方第|k|条对角线构成一个具有m+k个元素的向量；当k=0，则等同于diag(A)。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">% 创建对角阵</span></span>
<span class="line"><span style="color:#839496;">V = [</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#D33682;"> 3</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">diag(V)              </span><span style="color:#586E75;font-style:italic;">% 主对角线</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 输出：</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">%     1     0     0</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">%     0     2     0</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">%     0     0     3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">diag(V,</span><span style="color:#D33682;">1</span><span style="color:#839496;">)            </span><span style="color:#586E75;font-style:italic;">% 上方第一条对角线</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 输出：</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">%     0     1     0     0</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">%     0     0     2     0</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">%     0     0     0     3</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">%     0     0     0     0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 提取对角线</span></span>
<span class="line"><span style="color:#839496;">A = magic(</span><span style="color:#D33682;">3</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#839496;">diag(A)              </span><span style="color:#586E75;font-style:italic;">% 提取主对角线 → [8;5;2]</span></span>
<span class="line"><span style="color:#839496;">diag(A,-</span><span style="color:#D33682;">1</span><span style="color:#839496;">)           </span><span style="color:#586E75;font-style:italic;">% 提取下方第一条对角线 → [4;9]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h3 id="_8-上三角阵" tabindex="-1">8. 上三角阵 <a class="header-anchor" href="#_8-上三角阵" aria-label="Permalink to &quot;8. 上三角阵&quot;">​</a></h3><p>使用格式为triu(A)、triu(A,k) 设A为m n阶矩阵，triu(A)将从矩阵A中提取主对角线之上的上三角部分构成一个m n阶上三角阵；triu(A,k)将从矩阵A中提取主对角线第|k|条对角线之上的上三角部分构成一个m n阶上三角阵。注意：这里的k与diag(A,k)的用法类似，当k＞0，则该对角线位于主对角线的上方第k条；当k＜0，该对角线位于主对角线的下方第|k|条；当k=0，则等同于triu (A)</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">A = magic(</span><span style="color:#D33682;">4</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#839496;">triu(A)              </span><span style="color:#586E75;font-style:italic;">% 标准上三角</span></span>
<span class="line"><span style="color:#839496;">triu(A,</span><span style="color:#D33682;">1</span><span style="color:#839496;">)            </span><span style="color:#586E75;font-style:italic;">% 主对角线以上第1条对角线开始</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_9-下三角阵" tabindex="-1">9. 下三角阵 <a class="header-anchor" href="#_9-下三角阵" aria-label="Permalink to &quot;9. 下三角阵&quot;">​</a></h3><p>tril的功能是从矩阵A中提取下三角部分构成下三角阵。用法与triu相同。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">tril(A)              </span><span style="color:#586E75;font-style:italic;">% 标准下三角</span></span>
<span class="line"><span style="color:#839496;">tril(A,-</span><span style="color:#D33682;">1</span><span style="color:#839496;">)           </span><span style="color:#586E75;font-style:italic;">% 主对角线以下第1条对角线开始</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_10-空矩阵" tabindex="-1">10. 空矩阵 <a class="header-anchor" href="#_10-空矩阵" aria-label="Permalink to &quot;10. 空矩阵&quot;">​</a></h3><p>在MATLAB里，把行数、列数为零的矩阵定义为空矩阵。空矩阵在数学意义上讲是空的，但在MATLAB里确是很有用的。例如</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">A=[</span><span style="color:#D33682;">0.1</span><span style="color:#D33682;"> 0.2</span><span style="color:#D33682;"> 0.3</span><span style="color:#839496;">;0.4 </span><span style="color:#D33682;">0.5</span><span style="color:#D33682;"> 0.6</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">B=find(A&gt;1.0)</span></span>
<span class="line"><span style="color:#839496;">B = [ ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这里<code>[ ]</code>是空矩阵的符号，B=find(A&gt;1.0)表示列出矩阵A中值大于1.0的元素的序号。当不能满足括号中的条件时，返回空矩阵。另外，也可以将空矩阵赋给一个变量，如：</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">B=[ ]</span></span>
<span class="line"><span style="color:#839496;">B = [ ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">B = find(A&gt;100)      </span><span style="color:#586E75;font-style:italic;">% 返回空矩阵[]</span></span>
<span class="line"><span style="color:#839496;">C = [];              </span><span style="color:#586E75;font-style:italic;">% 创建空矩阵</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="二、矩阵的特征值与特征向量" tabindex="-1">二、矩阵的特征值与特征向量 <a class="header-anchor" href="#二、矩阵的特征值与特征向量" aria-label="Permalink to &quot;二、矩阵的特征值与特征向量&quot;">​</a></h2><p>对于N N阶方阵A，所谓A的特征值问题是：求数λ和N维非零向量x（通常为复数），使之满足下式： A. x=λ x 则称λ为矩阵A的一个特征值（特征根），而非零向量x为矩阵A的特征值λ所对应的特征向量。 对一般的N N阶方阵A，其特征值通常为复数，若A为实对称矩阵，则A的特征值为实数。</p><h3 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h3><p>MATLAB提供的内部函数eig可以用来计算特征值与特征向量。eig函数的使用格式有五种，其中常见的有E=eig(A)、<code>[V,D]=eig(A)</code>和<code>[V,D]=eig(A,’nobalance’)</code>三种，另外两种格式用来计算矩阵的广义特征值与特征向量：E=eig(A,B)和<code>[V,D]=eig(A,B)</code>。</p><blockquote><p>E=eig(A)：由eig(A)返回方阵A的N个特征值，构成向量E；</p></blockquote><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">A = [</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">; </span><span style="color:#D33682;">2</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">E = eig(A)           </span><span style="color:#586E75;font-style:italic;">% 获取特征值 → [3; -1]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">[V,D] = eig(A)       </span><span style="color:#586E75;font-style:italic;">% 获取特征向量和特征值</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% V = 特征向量矩阵</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% D = 对角特征值矩阵</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="实对称矩阵示例" tabindex="-1">实对称矩阵示例 <a class="header-anchor" href="#实对称矩阵示例" aria-label="Permalink to &quot;实对称矩阵示例&quot;">​</a></h3><blockquote><p><code>[V,D]=eig(A)</code>：由eig(A)返回方阵A的N个特征值，构成NN阶对角阵D，其对角线上的N个元素即为相应的特征值，同时将返回相应的特征向量赋予NN阶方阵V的对应列，且A、V、D满足A V=V D；</p></blockquote><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">B = [</span><span style="color:#D33682;">2</span><span style="color:#839496;"> -</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 0</span><span style="color:#839496;">; -</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;"> -</span><span style="color:#D33682;">1</span><span style="color:#839496;">; </span><span style="color:#D33682;">0</span><span style="color:#839496;"> -</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">[VB, DB] = eig(B)    </span><span style="color:#586E75;font-style:italic;">% 特征值为实数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="广义特征值问题" tabindex="-1">广义特征值问题 <a class="header-anchor" href="#广义特征值问题" aria-label="Permalink to &quot;广义特征值问题&quot;">​</a></h3><blockquote><p><code>[V,D]=eig(A,’nobalance’)</code>：本格式的功能与格式(2)一样，只是格式(2)是先对A作相似变换(balance)，然后再求其特征值与相应的特征向量；而本格式则事先不作相似变换；</p></blockquote><blockquote><p>E=eig(A,B)：由eig(A,B)返回N N阶方阵A和B的N个广义特征值，构成向量E。</p></blockquote><blockquote><p><code>[V,D]=eig(A,B)</code>：由eig(A,B)返回方阵A和B的N个广义特征值，构成N N阶对角阵D，其对角线上的N个元素即为相应的广义特征值，同时将返回相应的特征向量构成NN阶满秩矩阵，且 满足A V=B V D。</p></blockquote><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">A = [</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">; </span><span style="color:#D33682;">3</span><span style="color:#D33682;"> 4</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">B = [</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">; </span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">[Vg, Dg] = eig(A,B)  </span><span style="color:#586E75;font-style:italic;">% 解广义特征值问题</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="三、行列式计算" tabindex="-1">三、行列式计算 <a class="header-anchor" href="#三、行列式计算" aria-label="Permalink to &quot;三、行列式计算&quot;">​</a></h2><p>MATLAB提供的内部函数det用来计算矩阵的行列式的值。设矩阵A为一方阵(必须是方阵)，求矩阵A的行列式值的格式为：det(A)。注意：本函数同样能计算通过构造出的稀疏矩阵的行列式的值。关于如何构造稀疏矩阵，将在本章最后一节介绍。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">A = [</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">; </span><span style="color:#D33682;">3</span><span style="color:#D33682;"> 4</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">det(A)               </span><span style="color:#586E75;font-style:italic;">% 行列式值 → -2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 稀疏矩阵示例</span></span>
<span class="line"><span style="color:#839496;">S = sparse([</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">; </span><span style="color:#D33682;">2</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">]);</span></span>
<span class="line"><span style="color:#839496;">det(S)               </span><span style="color:#586E75;font-style:italic;">% 仍可计算 → 1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="四、矩阵求逆与方程组求解" tabindex="-1">四、矩阵求逆与方程组求解 <a class="header-anchor" href="#四、矩阵求逆与方程组求解" aria-label="Permalink to &quot;四、矩阵求逆与方程组求解&quot;">​</a></h2><h3 id="_1-矩阵求逆" tabindex="-1">1. 矩阵求逆 <a class="header-anchor" href="#_1-矩阵求逆" aria-label="Permalink to &quot;1. 矩阵求逆&quot;">​</a></h3><p>若方阵A,B满足等式 <code>A*B = B*A = I (I为单位矩阵)</code> 则称A为B的逆矩阵，或称B为A的逆矩阵。这时A，B都称为可逆矩阵(或非奇异矩阵、或满秩矩阵)，否则称为不可逆矩阵(或奇异矩阵、或降秩矩阵)。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">A = [</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">; </span><span style="color:#D33682;">3</span><span style="color:#D33682;"> 4</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">A_inv = inv(A)       </span><span style="color:#586E75;font-style:italic;">% 矩阵逆</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 验证：</span></span>
<span class="line"><span style="color:#839496;">A </span><span style="color:#859900;">*</span><span style="color:#839496;"> A_inv            </span><span style="color:#586E75;font-style:italic;">% ≈ eye(2)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_2-矩阵求逆解法" tabindex="-1">2. 矩阵求逆解法 <a class="header-anchor" href="#_2-矩阵求逆解法" aria-label="Permalink to &quot;2. 矩阵求逆解法&quot;">​</a></h3><p>利用求系数矩阵A的逆阵A<sup>-1</sup>，我们可以得到矩阵求逆解法。对于线性代数方程组Ax=b，等号两侧各左乘A-1，有： A<sup>-1</sup>Ax=A-1b 由于A<sup>-1</sup>A=I，故得： x=A<sup>-1</sup>b</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">b = [</span><span style="color:#D33682;">5</span><span style="color:#839496;">; </span><span style="color:#D33682;">11</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">x = inv(A)*b         </span><span style="color:#586E75;font-style:italic;">% 解方程组Ax=b</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-直接解法-推荐" tabindex="-1">3. 直接解法（推荐） <a class="header-anchor" href="#_3-直接解法-推荐" aria-label="Permalink to &quot;3. 直接解法（推荐）&quot;">​</a></h3><p>对于线性代数方程组<code>Ax=b</code>，我们可以运用左除运算符“\\”象解一元一次方程那样简单地求解： <code>x=A\\b</code> 当系数矩阵A为<code>N*N</code>的方阵时，MATLAB会自行用高斯消去法求解线性代数方程组。若右端项b为<code>N*1</code>的列向量，则x=A\\b可获得方程组的数值解x（<code>N*1</code>的列向量）；若右端项b为<code>N*M</code>的矩阵，则<code>x=A\\b</code>可同时获得同一系数矩阵A、M个方程组数值解x（为<code>N*M</code>的矩阵），即<code>x(:,j)=A\\b(:,j)，j=1,2,…M</code>。</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">x = A\\b              </span><span style="color:#586E75;font-style:italic;">% 更高效的解法</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">% 多方程组示例</span></span>
<span class="line"><span style="color:#839496;">B = [</span><span style="color:#D33682;">5</span><span style="color:#D33682;"> 6</span><span style="color:#839496;">; </span><span style="color:#D33682;">11</span><span style="color:#D33682;"> 12</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">X = A\\B              </span><span style="color:#586E75;font-style:italic;">% 同时解AX=B的两个方程组</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="病态矩阵示例" tabindex="-1">病态矩阵示例 <a class="header-anchor" href="#病态矩阵示例" aria-label="Permalink to &quot;病态矩阵示例&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">H = hilb(</span><span style="color:#D33682;">5</span><span style="color:#839496;">);         </span><span style="color:#586E75;font-style:italic;">% 5阶Hilbert矩阵</span></span>
<span class="line"><span style="color:#839496;">cond(H)              </span><span style="color:#586E75;font-style:italic;">% 查看条件数</span></span>
<span class="line"><span style="color:#839496;">b = ones(</span><span style="color:#D33682;">5</span><span style="color:#839496;">,</span><span style="color:#D33682;">1</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#839496;">x = H\\b              </span><span style="color:#586E75;font-style:italic;">% 即使H病态也能求解</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="稀疏系统求解" tabindex="-1">稀疏系统求解 <a class="header-anchor" href="#稀疏系统求解" aria-label="Permalink to &quot;稀疏系统求解&quot;">​</a></h3><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">S = sparse([</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">; </span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">; </span><span style="color:#D33682;">2</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">], [</span><span style="color:#D33682;">1</span><span style="color:#D33682;"> 2</span><span style="color:#D33682;"> 2</span><span style="color:#839496;">], [</span><span style="color:#D33682;">3</span><span style="color:#D33682;"> 4</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">]);</span></span>
<span class="line"><span style="color:#839496;">b = [</span><span style="color:#D33682;">5</span><span style="color:#839496;">; </span><span style="color:#D33682;">1</span><span style="color:#839496;">];</span></span>
<span class="line"><span style="color:#839496;">x = S\\b              </span><span style="color:#586E75;font-style:italic;">% 稀疏矩阵高效求解</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr>`,65)]))}const u=a(p,[["render",o]]);export{y as __pageData,u as default};
